// Bitacora: agrega un renglon a la hoja "Reservas" de Google Sheets
async function bitacora(estado, d) {
  if (!SHEET_ID) return;
  try {
    const hoy = new Date().toLocaleString("es-MX", { timeZone: "America/Mexico_City" });
    await sheets.spreadsheets.values.append({
      spreadsheetId: SHEET_ID,
      range: "Reservas!A:K",
      valueInputOption: "USER_ENTERED",
      resource: { values: [[hoy, estado, d.nombre || "", d.telefono || "", d.llegada || "", d.salida || "", d.adultos ?? "", d.ninos ?? "", (d.motivo || "") + (d.paquetes ? ` · Paquetes: ${d.paquetes}` : ""), d.total ?? "", d.eventoId || ""]] },
    });
  } catch (e) {
    console.error("Bitacora:", e.message);
  }
}

// "22/09/2026" o "22-09-2026" -> "2026-09-22"
function aISO(fecha) {
  const [d, m, a] = String(fecha).trim().split(/[\/\-\.]/);
  return `${a}-${m.padStart(2, "0")}-${d.padStart(2, "0")}`;
}

// Detecta fechas en casi cualquier formato: "15 al 17 de noviembre", "15-17 nov", "15/11 al 17/11",
// "15/11/2026-17/11/2026", "15noviembre 17noviembre", "30 de nov al 2 de dic"... -> { llegada, salida } en DD/MM/YYYY
function extraerFechas(texto) {
  const t = String(texto).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, " ");
  const MES = { ene: 1, feb: 2, mar: 3, abr: 4, may: 5, jun: 6, jul: 7, ago: 8, sep: 9, set: 9, oct: 10, nov: 11, dic: 12 };
  const M = "(ene|feb|mar|abr|may|jun|jul|ago|sep|set|oct|nov|dic)[a-z]*\\.?";
  const hoy = new Date(); hoy.setHours(0, 0, 0, 0);
  const anio = (d, m, a) => {
    if (a) return a < 100 ? 2000 + a : a;
    const y = hoy.getFullYear();
    return new Date(y, m - 1, d) < hoy ? y + 1 : y;
  };
  const fmt = (d, m, a) => `${String(d).padStart(2, "0")}/${String(m).padStart(2, "0")}/${a}`;
  const ok = (d, m) => d >= 1 && d <= 31 && m >= 1 && m <= 12;
  let f = [];
  // "15 al 17 de noviembre" / "15-17 nov"
  let r = t.match(new RegExp("(\\d{1,2})\\s*(?:al|a|y|-|–|hasta(?: el)?)\\s*(?:el )?(?:(?:lunes|martes|miercoles|jueves|viernes|sabado|domingo)\\s*)?(\\d{1,2})\\s*(?:de\\s*)?" + M + "(?:\\s*(?:de|del)?\\s*(\\d{4}))?"));
  if (r) {
    const m2 = MES[r[3]], d1 = +r[1], d2 = +r[2], a = r[4] ? +r[4] : null;
    const m1 = d2 < d1 ? (m2 === 1 ? 12 : m2 - 1) : m2;
    if (ok(d1, m1) && ok(d2, m2)) f = [[d1, m1, a], [d2, m2, a]];
  }
  if (f.length < 2) {
    f = [];
    const re = new RegExp("(\\d{1,2})\\s*(?:de\\s*)?" + M + "(?:\\s*(?:de|del)?\\s*(\\d{4}))?|(\\d{1,2})\\s*[\\/\\-\\.]\\s*(\\d{1,2})(?:\\s*[\\/\\-\\.]\\s*(\\d{2,4}))?", "g");
    for (const x of t.matchAll(re)) {
      if (x[1] && ok(+x[1], MES[x[2]])) f.push([+x[1], MES[x[2]], x[3] ? +x[3] : null]);
      else if (x[4] && ok(+x[4], +x[5])) f.push([+x[4], +x[5], x[6] ? +x[6] : null]);
      if (f.length === 2) break;
    }
  }
  if (f.length < 2) {
    const s = t.match(/(\d{1,2}) (\d{1,2})(?: (\d{4}))? (?:al|a|-|y|hasta) (\d{1,2}) (\d{1,2})(?: (\d{4}))?/);
    if (s && ok(+s[1], +s[2]) && ok(+s[4], +s[5])) f = [[+s[1], +s[2], s[3] ? +s[3] : null], [+s[4], +s[5], s[6] ? +s[6] : null]];
  }
  if (f.length < 2) {
    const W = "(?:lunes|martes|miercoles|jueves|viernes|sabado|domingo)";
    const q = t.match(new RegExp(M + "(?:\\s*(?:de|del)?\\s*(\\d{4}))?[\\s,.:]*(?:(?:el|del|" + W + ")[\\s,.:]*)*(\\d{1,2})(?!\\d)[\\s,.:]*(?:(?:al|a|y|hasta|-|el|del|" + W + ")[\\s,.:]*)*(\\d{1,2})(?!\\d)"));
    if (q && ok(+q[3], MES[q[1]]) && ok(+q[4], MES[q[1]]) && +q[4] > +q[3]) f = [[+q[3], MES[q[1]], q[2] ? +q[2] : null], [+q[4], MES[q[1]], q[2] ? +q[2] : null]];
  }
  if (f.length < 2) return null;
  const [a1, a2] = [f[0], f[1]];
  const y1 = anio(a1[0], a1[1], a1[2] || a2[2]);
  let y2 = a2[2] ? (a2[2] < 100 ? 2000 + a2[2] : a2[2]) : y1;
  if (new Date(y2, a2[1] - 1, a2[0]) <= new Date(y1, a1[1] - 1, a1[0])) y2 = y1 + 1;
  if (new Date(y2, a2[1] - 1, a2[0]) - new Date(y1, a1[1] - 1, a1[0]) > 30 * 86400000) return null;
  return { llegada: fmt(a1[0], a1[1], y1), salida: fmt(a2[0], a2[1], y2) };
}

// Solo cuentan como reserva los eventos de color mostaza (o los que creo el agente). Configurable en Railway: COLORES_RESERVA="5,8"
const COLORES_RESERVA = String(process.env.COLORES_RESERVA || "5,8").split(",").map(s => s.trim());
const esReserva = e => !!(e.extendedProperties?.private?.estado) || !e.colorId || COLORES_RESERVA.includes(String(e.colorId));

async function consultarUnaVez(llegada, salida) {
  const r = await calendar.events.list({
    calendarId: CALENDAR_ID,
    timeMin: `${aISO(llegada)}T13:00:00-06:00`,
    timeMax: `${aISO(salida)}T12:00:00-06:00`,
    singleEvents: true,
  });
  const todos = (r.data.items || []).filter(e => e.status !== "cancelled");
  // Mismo criterio que la imagen del calendario: el evento debe pisar alguna noche real (13:00 llegada - 12:00 salida)
  const ocupados = todos.filter(esReserva).filter(e => solapaEstancia(e, aISO(llegada), aISO(salida)));
  if (todos.length !== ocupados.length) console.log("Eventos ignorados (no son color de reserva):", todos.filter(e => !esReserva(e)).map(e => e.summary + " [color " + (e.colorId || "default") + "]").join(" | "));
  return { disponible: ocupados.length === 0, eventos: ocupados };
}

// Rango real de un evento. Los de "todo el dia" (Airbnb, bloqueos a mano) se leen como llegada 13:00 -> salida 12:00,
// asi un evento del 14 al 16 ocupa las noches 14 y 15, y no bloquea por error la noche del 13.
function rangoEvento(e) {
  if (e.start.date) return [Date.parse(`${e.start.date}T13:00:00-06:00`), Date.parse(`${e.end.date}T12:00:00-06:00`)];
  return [Date.parse(e.start.dateTime), Date.parse(e.end.dateTime)];
}
function solapaEstancia(e, llegadaISO, salidaISO) {
  const [s, f] = rangoEvento(e);
  return s < Date.parse(`${salidaISO}T12:00:00-06:00`) && f > Date.parse(`${llegadaISO}T13:00:00-06:00`);
}
const sigDia = iso => new Date(Date.parse(iso + "T12:00:00Z") + 86400000).toISOString().slice(0, 10);

// Doble verificacion: consulta el calendario 2 veces (con 1.5 s de pausa); si alguna dice ocupado, esta ocupado
async function consultarDisponibilidad(llegada, salida) {
  const v1 = await consultarUnaVez(llegada, salida);
  await new Promise(r => setTimeout(r, 1500));
  const v2 = await consultarUnaVez(llegada, salida);
  const disponible = v1.disponible && v2.disponible;
  console.log("Doble verificacion", llegada, "-", salida, "| 1:", v1.disponible ? "LIBRE" : "OCUPADO", "| 2:", v2.disponible ? "LIBRE" : "OCUPADO");
  return { disponible };
}

async function crearEventoCalendar(datos) {
  if (Number(datos.adultos || 0) + Number(datos.ninos || 0) > 20) return { excedido: true };
  const { disponible } = await consultarDisponibilidad(datos.llegada, datos.salida);
  if (!disponible) return { ocupado: true };
  cacheCal.clear(); // la imagen del calendario se regenera con la nueva reserva
  const evento = await calendar.events.insert({
    calendarId: CALENDAR_ID,
    resource: {
      summary: `⏳ PENDIENTE - ${datos.nombre}`,
      colorId: "8",
      extendedProperties: { private: { contacto: String(datos.contacto || ""), telefono: String(datos.telefono || ""), estado: "pendiente" } },
      description: `Adultos: ${datos.adultos}\nNinos: ${datos.ninos || 0}\nMotivo: ${datos.motivo || "-"}\nPaquetes: ${datos.paquetes || "Ninguno"}\nTelefono: ${datos.telefono || "-"}`,
      start: { dateTime: `${aISO(datos.llegada)}T13:00:00`, timeZone: "America/Mexico_City" },
      end: { dateTime: `${aISO(datos.salida)}T12:00:00`, timeZone: "America/Mexico_City" },
    },
  });
  // Verificacion posterior: si otro evento se agendo al mismo tiempo, se borra este y se avisa ocupado
  const despues = await consultarUnaVez(datos.llegada, datos.salida);
  if (despues.eventos.some(e => e.id !== evento.data.id)) {
    await calendar.events.delete({ calendarId: CALENDAR_ID, eventId: evento.data.id });
    console.log("Choque de reservas detectado, evento revertido:", evento.data.id);
    return { ocupado: true };
  }
  return { ocupado: false, id: evento.data.id };
}

async function confirmarReservas(contacto) {
  const r = await calendar.events.list({
    calendarId: CALENDAR_ID,
    privateExtendedProperty: [`contacto=${contacto}`, "estado=pendiente"],
    singleEvents: true,
  });
  const pendientes = (r.data.items || []).filter(e => e.status !== "cancelled");
  for (const e of pendientes) {
    await calendar.events.patch({
      calendarId: CALENDAR_ID,
      eventId: e.id,
      resource: {
        summary: e.summary.replace("⏳ PENDIENTE", "✅ CONFIRMADA"),
        colorId: "5",
        extendedProperties: { private: { ...(e.extendedProperties?.private || {}), estado: "confirmada" } },
      },
    });
    const p = e.extendedProperties?.private || {};
    const fmt = s => (s || "").slice(0, 10).split("-").reverse().join("/");
    await bitacora("Confirmada", { nombre: e.summary.replace(/^.*?-\s*/, ""), telefono: p.telefono, llegada: fmt(e.start.dateTime || e.start.date), salida: fmt(e.end.dateTime || e.end.date), eventoId: e.id });
    console.log("Reserva confirmada en Calendar:", e.id);
  }
  return pendientes.length;
}

// Mensaje post-estancia: 24 h despues del check-out dispara un flujo de ManyChat (plantilla de WhatsApp)
async function enviarPostEstancia() {
  if (!process.env.MANYCHAT_API_KEY || !process.env.MANYCHAT_FLOW_RESENA) return;
  const ahora = Date.now();
  const r = await calendar.events.list({
    calendarId: CALENDAR_ID,
    timeMin: new Date(ahora - 5 * 86400000).toISOString(),
    timeMax: new Date(ahora - 86400000).toISOString(),
    privateExtendedProperty: ["estado=confirmada"],
    singleEvents: true,
  });
  for (const e of r.data.items || []) {
    const p = e.extendedProperties?.private || {};
    const fin = new Date(e.end.dateTime || e.end.date).getTime();
    if (p.resena === "enviada" || !p.contacto || ahora - fin < 86400000) continue;
    try {
      const resp = await fetch("https://api.manychat.com/fb/sending/sendFlow", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${process.env.MANYCHAT_API_KEY}` },
        body: JSON.stringify({ subscriber_id: p.contacto, flow_ns: process.env.MANYCHAT_FLOW_RESENA }),
      });
      const data = await resp.json();
      if (data.status !== "success") { console.error("ManyChat post-estancia:", JSON.stringify(data)); continue; }
      await calendar.events.patch({
        calendarId: CALENDAR_ID,
        eventId: e.id,
        resource: { extendedProperties: { private: { ...p, resena: "enviada" } } },
      });
      console.log("Mensaje post-estancia enviado:", e.summary);
    } catch (err) {
      console.error("Error post-estancia:", err.message);
    }
  }
}

async function manychat(ruta, body) {
  const resp = await fetch("https://api.manychat.com/fb/sending/" + ruta, {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${process.env.MANYCHAT_API_KEY}` },
    body: JSON.stringify(body),
  });
  return resp.json();
}
const textoWA = (subscriber_id, text) => manychat("sendContent", { subscriber_id, data: { version: "v2", content: { type: "whatsapp", messages: [{ type: "text", text }] } } });

// Aviso por WhatsApp a los administradores (plantilla de ManyChat) cuando un huesped necesita atencion.
// AVISO_ADMINS = codigos de contacto de ManyChat separados por coma (cada admin lo obtiene escribiendo ACTIVAR AVISOS)
const ADMINS_AVISO = String(process.env.AVISO_ADMINS || "").split(/[\s,;]+/).filter(Boolean);
const avisosEnviados = new Map(); // admin -> hora del ultimo aviso (para no contestarle su "ok")
const URL_PUBLICA = process.env.URL_PUBLICA || (process.env.RAILWAY_PUBLIC_DOMAIN ? `https://${process.env.RAILWAY_PUBLIC_DOMAIN}` : "https://villa-canto-agente-production.up.railway.app");
async function avisarAdmins({ id, telefono, texto, nombre }) {
  const info = id ? await infoContacto(id) : {};
  nombre = nombre || info.name || [info.first_name, info.last_name].filter(Boolean).join(" ") || "Un huésped";
  const d = String(info.whatsapp_phone || (telefono && !String(telefono).includes("{{") ? telefono : "")).replace(/\D/g, "").slice(-10);
  const telF = d.length === 10 ? `${d.slice(0, 3)} ${d.slice(3, 6)} ${d.slice(6)}` : "";
  const tel = telF ? ` (${telF})` : "";
  const dijo = String(texto || "").replace(/\s+/g, " ").trim().slice(0, 180);
  // Grupo de WhatsApp de los administradores (via Whapi.cloud): WHAPI_TOKEN y WHAPI_GRUPO en Railway
  if (process.env.WHAPI_TOKEN && process.env.WHAPI_GRUPO) {
    const mensaje = [
      "🔔 *Villa de Canto · un huésped necesita atención*",
      "",
      `👤 ${nombre}`,
      telF ? `📱 ${telF}` : null,
      `💬 "${dijo || "Quiere hablar con el administrador"}"`,
      "",
      "⏸️ Vero quedó en pausa con este huésped. Contesten desde el WhatsApp de la villa (442 874 2383).",
      id ? `▶️ Para reactivar a Vero: ${URL_PUBLICA}/reanudar/${id}` : null,
    ].filter(x => x != null).join("\n");
    try {
      const r = await fetch("https://gate.whapi.cloud/messages/text", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${process.env.WHAPI_TOKEN.trim()}` },
        body: JSON.stringify({ to: process.env.WHAPI_GRUPO.trim(), body: mensaje }),
      });
      const c = await r.json().catch(() => ({}));
      if (!r.ok || c.sent === false) { console.error("Aviso al grupo:", r.status, JSON.stringify(c)); return [`❌ Grupo: ${r.status} ${JSON.stringify(c).slice(0, 300)}`]; }
      console.log("Aviso enviado al grupo de administradores");
      return ["✅ Aviso enviado al grupo"];
    } catch (e) { console.error("Aviso al grupo:", e.message); return [`❌ Grupo: ${e.message}`]; }
  }
  if (!process.env.MANYCHAT_API_KEY || !process.env.MANYCHAT_FLOW_AVISO || !ADMINS_AVISO.length) {
    const faltan = [!process.env.MANYCHAT_API_KEY && "MANYCHAT_API_KEY", !process.env.MANYCHAT_FLOW_AVISO && "MANYCHAT_FLOW_AVISO", !ADMINS_AVISO.length && "AVISO_ADMINS"].filter(Boolean).join(", ");
    console.error("AVISO NO ENVIADO: faltan en Railway", faltan);
    return [`❌ Faltan en Railway: ${faltan}`];
  }
  const valor = `${nombre}${tel} escribió: ${dijo || "quiere hablar con el administrador"}`.replace(/\s+/g, " ").replace(/[.\s]+$/, "").trim();
  const out = [];
  for (const admin of ADMINS_AVISO) {
    try {
      const r = await fetch("https://api.manychat.com/fb/subscriber/setCustomFieldByName", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${process.env.MANYCHAT_API_KEY}` },
        body: JSON.stringify({ subscriber_id: admin, field_name: "aviso_admin", field_value: valor }),
      });
      const c = await r.json();
      if (c.status !== "success") { console.error("Aviso admin (campo aviso_admin):", admin, JSON.stringify(c)); out.push(`❌ ${admin}: ${JSON.stringify(c)}`); continue; }
      // Hasta 3 intentos: ManyChat a veces falla un momento y el aviso se perdia
      let s = {};
      for (let i = 0; i < 3; i++) {
        try { s = await manychat("sendFlow", { subscriber_id: admin, flow_ns: process.env.MANYCHAT_FLOW_AVISO }); } catch (e) { s = { status: "error", message: e.message }; }
        if (s.status === "success") break;
        await new Promise(r => setTimeout(r, 2000 * (i + 1)));
      }
      if (s.status !== "success") { console.error("Aviso admin (envio):", admin, JSON.stringify(s)); out.push(`❌ ${admin}: ${JSON.stringify(s)}`); continue; }
      avisosEnviados.set(String(admin), Date.now());
      console.log("Aviso por WhatsApp enviado al administrador", admin);
      out.push(`✅ ${admin}`);
    } catch (e) { console.error("Aviso admin:", admin, e.message); out.push(`❌ ${admin}: ${e.message}`); }
  }
  return out;
}

// 1) Liberar reservas pendientes sin pago despues de HORAS_PENDIENTE (48 h por defecto)
async function liberarPendientes() {
  const horas = Number(process.env.HORAS_PENDIENTE || 48);
  const r = await calendar.events.list({ calendarId: CALENDAR_ID, privateExtendedProperty: ["estado=pendiente"], timeMin: new Date().toISOString(), singleEvents: true });
  for (const e of r.data.items || []) {
    if (Date.now() - new Date(e.created).getTime() < horas * 3600000) continue;
    const p = e.extendedProperties?.private || {};
    if (p.pago === "avisado") continue; // ya mando su comprobante: no se libera, lo confirma el administrador
    const fmt = s => (s || "").slice(0, 10).split("-").reverse().join("/");
    try {
      await calendar.events.delete({ calendarId: CALENDAR_ID, eventId: e.id });
      console.log("Reserva pendiente liberada:", e.summary);
      await bitacora("Liberada sin pago", { nombre: e.summary.replace(/^.*?-\s*/, ""), telefono: p.telefono, llegada: fmt(e.start.dateTime || e.start.date), salida: fmt(e.end.dateTime || e.end.date), eventoId: e.id });
      if (process.env.MANYCHAT_API_KEY && p.contacto) {
        const d = await textoWA(p.contacto, `Hola 🌿 Como no recibimos el anticipo, liberamos las fechas del ${fmt(e.start.dateTime || e.start.date)} al ${fmt(e.end.dateTime || e.end.date)}. Si aun te interesan, escribeme y reviso con gusto si siguen disponibles 😊`);
        if (d.status !== "success") console.log("Aviso de liberacion no enviado (fuera de 24 h):", JSON.stringify(d));
      }
    } catch (err) { console.error("Error liberando:", err.message); }
  }
}

// Recordatorio de cotizacion: si ya le dijimos que hay disponibilidad y dejo de contestar, el agente le escribe ~12 h
// despues de su ultimo mensaje. Si eso cae de noche (21:00 a 9:00), se pasa a las 10:00 de la manana siguiente.
// Si las 10:00 ya quedan fuera de las 24 h en que WhatsApp permite mensajes libres, se manda a las 20:30 de ese dia.
// Si dijo que no, ya no se le recuerda.
const MX = 6 * 3600000; // Ciudad de Mexico: UTC-6 todo el ano
const dbGet = (sql, args) => new Promise(ok => db.get(sql, args, (e, r) => ok(e ? null : r)));
function horaRecordatorio(creado) {
  const ideal = creado + Number(process.env.HORAS_RECORDATORIO_COTIZACION || 12) * 3600000;
  const loc = new Date(ideal - MX), h = loc.getUTCHours() + loc.getUTCMinutes() / 60;
  if (h >= 9 && h < 21) return ideal;
  const manana = new Date(loc);
  if (h >= 21) manana.setUTCDate(manana.getUTCDate() + 1);
  manana.setUTCHours(Number(process.env.HORA_RECORDATORIO_MANANA || 10), 0, 0, 0);
  if (manana.getTime() + MX - creado <= 22.5 * 3600000) return manana.getTime() + MX;
  loc.setUTCHours(20, 30, 0, 0); // la manana ya queda fuera de las 24 h: mejor esa misma tarde
  return loc.getTime() + MX;
}
async function marcarAvisoPago(contacto) {
  const r = await calendar.events.list({ calendarId: CALENDAR_ID, privateExtendedProperty: [`contacto=${contacto}`, "estado=pendiente"], singleEvents: true });
  for (const e of (r.data.items || []).filter(x => x.status !== "cancelled")) {
    await calendar.events.patch({ calendarId: CALENDAR_ID, eventId: e.id, resource: { extendedProperties: { private: { ...(e.extendedProperties?.private || {}), pago: "avisado" } } } });
  }
}
async function enviarRecordatorios() {
  if (!process.env.MANYCHAT_API_KEY) return;
  const ahora = Date.now(), loc = new Date(ahora - MX), hora = loc.getUTCHours() + loc.getUTCMinutes() / 60;
  if (hora < 9 || hora >= 21) return; // nunca de noche
  // Cotizaciones sin respuesta: recordatorio para quien pidio precio y dejo de contestar
  const cots = await new Promise(ok => db.all("SELECT * FROM cotizaciones WHERE recordatorio IS NULL", [], (e, r2) => ok(e ? [] : r2 || [])));
  for (const q of cots) {
    if (await dbGet("SELECT id FROM no_recordar WHERE id = ?", [q.id])) { db.run("UPDATE cotizaciones SET recordatorio = 'no' WHERE id = ?", [q.id]); continue; }
    const pausa = await dbGet("SELECT hasta FROM pausas WHERE id = ?", [q.id]);
    if (pausa && pausa.hasta > ahora) continue;
    try { const out = await recordarCotizacion(q); if (!String(out).startsWith("esperando")) console.log("Recordatorio de cotizacion", q.id, "->", String(out).slice(0, 120)); }
    catch (err) { console.error("Recordatorio de cotizacion:", err.message); }
  }
}
async function recordarCotizacion(q, forzar) {
  const conv = await dbGet("SELECT messages, updated_at FROM conversations WHERE id = ?", [q.id]);
  const ultimo = conv ? new Date(String(conv.updated_at).replace(" ", "T") + "Z").getTime() : q.creado;
  const marcar = estado => db.run("UPDATE cotizaciones SET recordatorio = ? WHERE id = ?", [estado, q.id]);
  if (!forzar && Date.now() < horaRecordatorio(ultimo)) return "esperando (el cliente escribio hace poco)";
  if (!forzar && Date.now() - ultimo > 23 * 3600000) { marcar("sin_ventana"); return "no enviado (pasaron mas de 24 h desde su ultimo mensaje)"; }
  if (aISO(q.llegada) <= new Date(Date.now() - MX).toISOString().slice(0, 10)) { marcar("vencida"); return "no enviado (la fecha ya paso)"; }
  const ev = await calendar.events.list({ calendarId: CALENDAR_ID, privateExtendedProperty: [`contacto=${q.id}`], timeMin: new Date().toISOString(), singleEvents: true, maxResults: 1 });
  if (!forzar && (ev.data.items || []).length) { marcar("aparto"); return "no enviado (ya tiene reserva)"; }
  const { disponible } = await consultarDisponibilidad(q.llegada, q.salida);
  if (!disponible) { marcar("ocupada"); return "no enviado (esas fechas ya se ocuparon)"; }
  const history = conv ? JSON.parse(conv.messages) : [];
  const hl = new Date(Date.now() - MX).getUTCHours(), saludo = hl < 12 ? "Buenos días" : hl < 19 ? "Buenas tardes" : "Buenas noches";
  const nota = `[SISTEMA] RECORDATORIO_COTIZACION (no lo escribio el cliente). Le dijiste que la villa esta disponible del ${q.llegada} al ${q.salida}, le cotizaste y dejo de contestar. Escribele TU ahora un mensaje corto (2 a 4 lineas), calido y sin presionar, en el idioma de la conversacion. Empieza con "${saludo}" y su nombre si lo sabes, y preguntale si quiere continuar con su reserva, por ejemplo: "¿Te gustaría continuar con tu reserva? 🌿". Cuentale que esas fechas siguen disponibles por ahora, pero que no quedan apartadas hasta recibir el anticipo y el deposito en garantia, asi que otra persona podria reservarlas. Ofrecele resolver dudas o ajustar la cotizacion. No repitas la cotizacion completa, no te presentes de nuevo, no saludes como reencuentro y nunca digas SISTEMA.`;
  const last = history[history.length - 1];
  if (last && last.role === "user") last.content = String(last.content) + "\n" + nota; else history.push({ role: "user", content: nota });
  let reply = "";
  try { reply = await responderConClaude(history, q.id); } catch (err) { console.error("Recordatorio cotizacion (Claude):", err.message); }
  reply = String(reply).replace(/COTIZACION_JSON:\{.*?\}|NO_INTERESADO|RESERVA_JSON[\s\S]*$|PASAR_A_HUMANO|FOTOS_CASA|FOTOS_PINATAS|ENVIAR_FOTOS|AVISO_PAGO|CALENDARIO:\S*/g, "").replace(/\*\*(.+?)\*\*/g, "*$1*").trim();
  if (!reply || /^Dame un momento/.test(reply)) reply = `${saludo} 🌿 ¿Te gustaría continuar con tu reserva del ${q.llegada} al ${q.salida}? Esas fechas siguen disponibles por ahora, pero se apartan hasta recibir el anticipo y el depósito en garantía. Si tienes alguna duda o quieres ajustar algo, aquí estoy 😊`;
  marcar("enviando");
  const d = await textoWA(q.id, reply);
  if (d.status !== "success") { marcar("fallido"); return "no enviado: " + JSON.stringify(d); }
  history.push({ role: "assistant", content: reply });
  while (history.length > 40) history.shift();
  while (history.length && history[0].role !== "user") history.shift();
  db.run("INSERT OR REPLACE INTO conversations (id, messages, updated_at) VALUES (?, ?, datetime('now'))", [q.id, JSON.stringify(history)]);
  marcar("enviado");
  await bitacora("Recordatorio de cotizacion", { telefono: q.id, llegada: q.llegada, salida: q.salida, total: q.total });
  return "enviado: " + reply;
}

// 5) Mensaje 1 dia antes de la llegada (plantilla de ManyChat)
async function enviarPreLlegada() {
  if (!process.env.MANYCHAT_API_KEY || !process.env.MANYCHAT_FLOW_LLEGADA) return;
  const ahora = Date.now();
  const r = await calendar.events.list({ calendarId: CALENDAR_ID, privateExtendedProperty: ["estado=confirmada"], timeMin: new Date(ahora).toISOString(), timeMax: new Date(ahora + 30 * 3600000).toISOString(), singleEvents: true });
  for (const e of r.data.items || []) {
    const p = e.extendedProperties?.private || {};
    if (p.prellegada === "enviada" || !p.contacto) continue;
    try {
      const d = await manychat("sendFlow", { subscriber_id: p.contacto, flow_ns: process.env.MANYCHAT_FLOW_LLEGADA });
      if (d.status !== "success") { console.error("Pre-llegada:", JSON.stringify(d)); continue; }
      await calendar.events.patch({ calendarId: CALENDAR_ID, eventId: e.id, resource: { extendedProperties: { private: { ...p, prellegada: "enviada" } } } });
      console.log("Mensaje pre-llegada enviado:", e.summary);
    } catch (err) { console.error("Error pre-llegada:", err.message); }
  }
}

// Recordatorio a los 5 dias: SOLO a quien pidio cotizacion con fechas, dejo de contestar y no tiene reserva
async function enviarSeguimientos() {
  if (!process.env.MANYCHAT_API_KEY || !process.env.MANYCHAT_FLOW_SEGUIMIENTO) return;
  const filas = await new Promise(ok => db.all(
    `SELECT c.id, c.updated_at FROM conversations c LEFT JOIN seguimiento s ON s.id = c.id
     WHERE c.updated_at <= datetime('now','-5 days') AND c.updated_at > datetime('now','-10 days')
     AND (s.enviado_para IS NULL OR s.enviado_para <> c.updated_at) AND c.id NOT IN (SELECT id FROM no_recordar)
     AND c.id IN (SELECT id FROM cotizaciones)`, [], (e, r) => ok(e ? [] : r || [])));
  for (const f of filas) {
    try {
      const r = await calendar.events.list({ calendarId: CALENDAR_ID, privateExtendedProperty: [`contacto=${f.id}`], singleEvents: true, maxResults: 1 });
      const marcar = () => db.run("INSERT OR REPLACE INTO seguimiento (id, enviado_para) VALUES (?, ?)", [f.id, f.updated_at]);
      if ((r.data.items || []).length) { marcar(); continue; }
      const resp = await fetch("https://api.manychat.com/fb/sending/sendFlow", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${process.env.MANYCHAT_API_KEY}` },
        body: JSON.stringify({ subscriber_id: f.id, flow_ns: process.env.MANYCHAT_FLOW_SEGUIMIENTO }),
      });
      const data = await resp.json();
      if (data.status !== "success") { console.error("Seguimiento:", JSON.stringify(data)); continue; }
      marcar();
      console.log("Recordatorio 5 dias enviado a", f.id);
    } catch (err) { console.error("Error seguimiento:", err.message); }
  }
}

