async function infoContacto(id) {
  if (!process.env.MANYCHAT_API_KEY) { console.error("Falta MANYCHAT_API_KEY para leer el mensaje"); return {}; }
  try {
    const r = await fetch("https://api.manychat.com/fb/subscriber/getInfo?subscriber_id=" + encodeURIComponent(id), { headers: { Authorization: "Bearer " + process.env.MANYCHAT_API_KEY } });
    const d = await r.json();
    if (d.status !== "success") { console.error("ManyChat getInfo:", JSON.stringify(d)); return {}; }
    return d.data || {};
  } catch (e) { console.error("ManyChat getInfo:", e.message); return {}; }
}

app.post("/webhook", async (req, res) => {
  res.t0 = Date.now();
  const b = req.body || {};
  const c = (b.last_input_text !== undefined ? b : Object.values(b).find(v => v && typeof v === "object" && "last_input_text" in v)) || {};
  let phoneNumber = b.phoneNumber || c.id;
  let telefono = b.telefono || c.whatsapp_phone || c.phone;
  let message = b.message || c.last_input_text;
  // ManyChat no puede mandar en el JSON mensajes con saltos de linea o comillas: el texto se lee directo de su API
  if (!message && phoneNumber) {
    const info = await infoContacto(phoneNumber);
    message = info.last_input_text || "";
    telefono = telefono || info.whatsapp_phone || info.phone || "";
    console.log("Mensaje leido de ManyChat:", JSON.stringify(String(message)).slice(0, 150));
  }
  if (message && /^https?:\/\/\S+$/i.test(String(message).trim())) {
    message = "[El cliente envio una imagen. Si ya le diste los datos bancarios, es su comprobante de pago]";
  }
  if (!phoneNumber || !message) return res.status(400).json({ error: "phoneNumber y message requeridos" });

  // ACTIVAR AVISOS: le da a esa persona su codigo para recibir los avisos por WhatsApp (se pega en AVISO_ADMINS)
  if (/^\W*activar\s+avisos\W*$/i.test(String(message))) {
    const ya = ADMINS_AVISO.includes(String(phoneNumber));
    console.log("ACTIVAR AVISOS desde", phoneNumber, ya ? "(ya registrado)" : "");
    return res.json({ response: ya ? "✅ Este número ya recibe los avisos de Villa de Canto." : `🔔 Tu código para recibir avisos es: ${phoneNumber}\n\nCompártelo con quien configura el agente para que lo agregue.`, avisoPago: "no", enviarFotos: "no", fotosPinatas: "no", avisoHumano: "no" });
  }
  // Si un administrador contesta el aviso con "ok", "voy", "gracias" o un emoji, el agente no le responde
  const tAviso = avisosEnviados.get(String(phoneNumber));
  if (tAviso && Date.now() - tAviso < 3600000 && (/^\W*(ok|okay|oki|va|vale|voy|enterado|entendido|gracias|listo|perfecto|sale|de acuerdo|si|sí)\W*$/i.test(String(message).trim()) || /^[\p{Extended_Pictographic}\s\u200d\ufe0f]+$/u.test(String(message)))) {
    return res.json({ response: "", omitir: "si", avisoPago: "no", enviarFotos: "no", fotosPinatas: "no", avisoHumano: "no" });
  }

  // PAUSA AUTOMATICA: cuando el administrador escribe a mano (WhatsApp o chat en vivo), ManyChat vuelve a mandar
  // el ultimo mensaje del cliente. Si llega repetido y Vero ya lo habia contestado, es el administrador: Vero se pausa.
  const msgN = String(message).trim(), ult = ultimoCliente.get(String(phoneNumber));
  if (ult && ult.texto === msgN && !msgN.startsWith("[") && Date.now() - ult.t > ECO_MIN_MS && Date.now() - ult.t < 48 * 3600000 && !pendientes.has(phoneNumber) && !procesando.has(phoneNumber)) {
    pausarPorAdmin(phoneNumber, "el administrador escribio al cliente");
    return res.json({ response: "", omitir: "si", avisoPago: "no", enviarFotos: "no", fotosPinatas: "no", avisoHumano: "no" });
  }

  // Espera ESPERA_MS por si el cliente manda varios mensajes seguidos; solo el ultimo contesta con todo junto
  if (String(message).startsWith("[SISTEMA]") || esReanudar(message) || esReiniciar(message) || esContinuar(message)) return procesarMensaje(phoneNumber, telefono, message, res);
  const p = pendientes.get(phoneNumber) || { textos: [] };
  if (p.timer) { clearTimeout(p.timer); p.res.json({ response: "", omitir: "si", avisoPago: "no", enviarFotos: "no", fotosPinatas: "no", avisoHumano: "no" }); }
  if (!p.textos.includes(String(message))) p.textos.push(String(message));
  // Si Vero esta contestando un mensaje anterior, esa respuesta se descarta y se contesta todo junto
  if (pensando.has(phoneNumber)) cancelados.add(phoneNumber);
  p.res = res;
  // Solo saludo ("hola", "buenas tardes"): casi siempre sigue otro mensaje. Se suelta a ManyChat y se espera mas
  let espera = ESPERA_MS;
  if (p.textos.length === 1 && esSaludo(message)) {
    res.json({ response: "", omitir: "si", avisoPago: "no", enviarFotos: "no", fotosPinatas: "no", avisoHumano: "no" });
    p.res = resPorApi(phoneNumber);
    espera = ESPERA_SALUDO_MS;
    console.log("Solo saludo de", phoneNumber, "- espero", espera / 1000, "s por si escribe algo mas");
  }
  const lanzar = () => {
    // Si todavia esta contestando un mensaje anterior, espera a que termine y junta todo
    if (procesando.has(phoneNumber) || pensando.has(phoneNumber)) { p.timer = setTimeout(lanzar, 700); return; }
    pendientes.delete(phoneNumber);
    procesando.add(phoneNumber);
    console.log("Procesando", p.textos.length, "mensaje(s) de", phoneNumber);
    Promise.resolve(procesarMensaje(phoneNumber, telefono, p.textos.join("\n"), p.res))
      .catch(e => console.error("Error procesando:", e.message))
      .finally(() => { procesando.delete(phoneNumber); ultimoCliente.set(String(phoneNumber), { texto: String(p.textos[p.textos.length - 1]).trim(), t: Date.now() }); });
  };
  p.timer = setTimeout(lanzar, espera);
  pendientes.set(phoneNumber, p);
});

const ESPERA_MS = Number(process.env.ESPERA_MS || 3000);
const ESPERA_SALUDO_MS = Number(process.env.ESPERA_SALUDO_MS || 25000);
const cancelados = new Set();
const ultimoCliente = new Map(); // contacto -> ultimo mensaje del cliente ya contestado (para detectar al administrador)
const ECO_MIN_MS = Number(process.env.ECO_MIN_MS || 5000);
function pausarPorAdmin(id, motivo) {
  const horas = Number(process.env.HORAS_PAUSA || 12);
  db.run("INSERT OR REPLACE INTO pausas (id, hasta) VALUES (?, ?)", [String(id), Date.now() + horas * 3600000]);
  const p = pendientes.get(id); if (p && p.timer) clearTimeout(p.timer);
  pendientes.delete(id); planGrupo.delete(id); grupoGrande.delete(id); ultimoCliente.delete(String(id));
  console.log("PAUSA AUTOMATICA:", motivo, "-", id, "- Vero en pausa", horas, "h");
}
const pensando = new Set(); // mientras Claude prepara la respuesta de ese contacto
const esSaludo = m => /^[\s\W]*((hola|holi|holaa+|buen[oa]s?|d[ií]as|tardes|noches|qu[eé] tal|que onda|info|informaci[oó]n|hey|hi|hello|saludos)[\s\W]*)+$/i.test(String(m).trim());
// Respuesta "falsa" para cuando ManyChat ya se solto: lo que se conteste se manda por la API de ManyChat
const resPorApi = id => ({ t0: Date.now() + 1e9, headersSent: false, status() { return this; }, json(o) { if (o && o.response && o.omitir !== "si") enviarPorManyChat(id, o.response); } });
// ManyChat corta la espera a los ~10 s. Si Claude tarda mas (revisando calendario), se contesta un "un momento"
// y la respuesta final se manda despues por la API de ManyChat (requiere MANYCHAT_API_KEY).
const LIMITE_MS = Number(process.env.LIMITE_MS || 8500); // tiempo total desde que llega el mensaje
const procesando = new Set();
const grupoGrande = new Map(); // clientes con grupo grande a los que les faltan fechas
const planGrupo = new Map();
async function enviarPorManyChat(id, texto) {
  if (!process.env.MANYCHAT_API_KEY) { console.error("Falta MANYCHAT_API_KEY: no se pudo mandar la respuesta tardia a", id); return; }
  try {
    const r = await fetch("https://api.manychat.com/fb/sending/sendContent", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${process.env.MANYCHAT_API_KEY}` },
      body: JSON.stringify({ subscriber_id: id, data: { version: "v2", content: { type: "whatsapp", messages: [{ type: "text", text: texto }] } } }),
    });
    const d = await r.json();
    console.log("Respuesta tardia enviada a", id, d.status, d.status === "success" ? "" : JSON.stringify(d));
  } catch (e) { console.error("Error respuesta tardia:", e.message); }
}
const pendientes = new Map();
const esReanudar = m => /^\W*(sistema\W*)?reanudar\W*$/i.test(String(m).trim());
const esReiniciar = m => /^\W*(sistema\W*)?reiniciar\W*$/i.test(String(m).trim());
function reiniciarContacto(id) {
  db.run("DELETE FROM pausas WHERE id = ?", [id]);
  db.run("DELETE FROM conversations WHERE id = ?", [id]);
  db.run("DELETE FROM seguimiento WHERE id = ?", [id]);
  db.run("DELETE FROM cotizaciones WHERE id = ?", [id]);
  db.run("DELETE FROM no_recordar WHERE id = ?", [id]);
  planGrupo.delete(id); grupoGrande.delete(id); pendientes.delete(id);
  console.log("Conversacion reiniciada para", id);
}

