// Agrega texto al historial sin llamar a Claude (se une al ultimo mensaje del cliente si lo hay)
function anotarHistorial(id, texto, cb) {
  db.get("SELECT messages FROM conversations WHERE id = ?", [id], (err, row) => {
    const h = row ? JSON.parse(row.messages) : [];
    const last = h[h.length - 1];
    if (last && last.role === "user") last.content = String(last.content) + "\n" + texto;
    else h.push({ role: "user", content: texto });
    db.run("INSERT OR REPLACE INTO conversations (id, messages, updated_at) VALUES (?, ?, datetime('now'))", [id, JSON.stringify(h)], () => cb && cb());
  });
}
const NOTA_REANUDAR = "[SISTEMA] El administrador de la villa ya atendio personalmente al cliente en este chat (tu no viste esa parte de la conversacion). Ya NO digas que lo vas a comunicar ni que el administrador le escribira. Si el cliente vuelve a escribir, retoma con naturalidad, como si fueras parte del mismo equipo: responde lo que pregunte y, si aplica, preguntale amablemente si quedo resuelto o si le ayudas con algo mas (fechas, cotizacion, paquetes).";

// CONTINUAR: quita la pausa, el agente lee toda la conversacion y retoma el hilo escribiendole al cliente
const esContinuar = m => /^\W*(sistema\W*)?continuar\b/i.test(String(m).trim());
function continuarContacto(id, nota) {
  return new Promise(resolve => {
    db.run("DELETE FROM pausas WHERE id = ?", [id]);
    const instruccion = "[SISTEMA] El administrador de la villa atendio personalmente al cliente en este chat y ahora te regresa la conversacion (tu no viste esa parte)." +
      (nota ? " Lo que el administrador acordo o aviso: " + nota + "." : "") +
      " Revisa TODA la conversacion anterior y escribele tu AHORA un mensaje corto, calido y natural al cliente para retomar donde se quedaron. PROHIBIDO volver a preguntarle lo que ya pidio o dijo (fechas, personas, paquete, motivo): resume en una frase lo que ya sabes (por ejemplo: Con gusto sigo con tu reserva de X adultos del ... al ...) y avanza al siguiente paso. No te presentes de nuevo, no saludes como si fuera un reencuentro (nada de que bueno verte de nuevo, de vuelta ni hola otra vez), no digas que el administrador le escribira. Arranca directo con el tema, por ejemplo mencionando sus fechas o su plan. Si faltan datos para su reserva (fechas, adultos, nombre), pide solo lo que falta; si ya estaba todo, preguntale si quedo resuelto o si le ayudas con algo mas.";
    anotarHistorial(id, instruccion, () => {
      db.get("SELECT messages FROM conversations WHERE id = ?", [id], async (err, row) => {
        try {
          const history = row ? JSON.parse(row.messages) : [];
          let reply = await responderConClaude(history, id);
          reply = String(reply).replace(/COTIZACION_JSON:\{.*?\}|NO_INTERESADO|PASAR_A_HUMANO|FOTOS_CASA|FOTOS_PINATAS|RESERVA_JSON[\s\S]*$/g, "").replace(/\*\*(.+?)\*\*/g, "*$1*").trim();
          if (!reply) return resolve("sin respuesta");
          history.push({ role: "assistant", content: reply });
          while (history.length > 40) history.shift();
          while (history.length && history[0].role !== "user") history.shift();
          db.run("INSERT OR REPLACE INTO conversations (id, messages, updated_at) VALUES (?, ?, datetime('now'))", [id, JSON.stringify(history)]);
          await enviarPorManyChat(id, reply);
          console.log("Agente CONTINUA la conversacion de", id);
          resolve(reply);
        } catch (e) { console.error("Continuar:", e.message); resolve("error: " + e.message); }
      });
    });
  });
}
app.get("/continuar/:id", async (req, res) => {
  console.log("CONTINUAR solicitado para", req.params.id, "| origen:", req.get("user-agent") || "?");
  const desdeManyChat = !/mozilla/i.test(req.get("user-agent") || "");
  if (desdeManyChat) {
    // ManyChat espera maximo ~10 s: se responde de inmediato y el mensaje se manda en segundo plano
    res.json({ status: "ok", continuar: "iniciado" });
    continuarContacto(req.params.id, req.query.nota || "").then(r => console.log("CONTINUAR resultado:", String(r).slice(0, 80)));
    return;
  }
  const r = await continuarContacto(req.params.id, req.query.nota || "");
  res.send("✅ El agente retomó la conversación con " + req.params.id + ".\n\nLe escribió: " + r);
});

function procesarMensaje(phoneNumber, telefono, message, res) {
  if (esContinuar(message)) {
    continuarContacto(phoneNumber, String(message).replace(/^\W*(sistema\W*)?continuar\b[\s:,.-]*/i, "").trim());
    return res.json({ response: "", omitir: "si", avisoPago: "no", enviarFotos: "no", fotosPinatas: "no", avisoHumano: "no" });
  }
  if (esReiniciar(message)) {
    reiniciarContacto(phoneNumber);
    return res.json({ response: "", omitir: "si", avisoPago: "no", enviarFotos: "no", fotosPinatas: "no", avisoHumano: "no" });
  }
  if (esReanudar(message)) {
    db.run("DELETE FROM pausas WHERE id = ?", [phoneNumber]);
    anotarHistorial(phoneNumber, NOTA_REANUDAR);
    console.log("Agente reanudado para", phoneNumber);
    return res.json({ response: "", omitir: "si", avisoPago: "no", enviarFotos: "no", fotosPinatas: "no", avisoHumano: "no" });
  }
  db.get("SELECT hasta FROM pausas WHERE id = ?", [phoneNumber], (e0, pausa) => {
    if (pausa && pausa.hasta <= Date.now()) {
      db.run("DELETE FROM pausas WHERE id = ?", [phoneNumber]);
      return anotarHistorial(phoneNumber, NOTA_REANUDAR, () => procesarConClaude(phoneNumber, telefono, message, res));
    }
    if (pausa && pausa.hasta > Date.now() && !String(message).startsWith("[SISTEMA]")) {
      console.log("Agente en pausa (lo atiende una persona):", phoneNumber);
      anotarHistorial(phoneNumber, "[Mensaje del cliente mientras lo atendia el administrador]: " + message);
      return res.json({ response: "", omitir: "si", avisoPago: "no", enviarFotos: "no", fotosPinatas: "no", avisoHumano: "no" });
    }
    procesarConClaude(phoneNumber, telefono, message, res);
  });
}

// Pide hablar con una persona: se detecta ANTES de llamar a Claude para pausar al instante
const MSG_HUMANO_ES = process.env.MENSAJE_HUMANO || "Con gusto 🌿 En breve un administrador de la villa se contactará contigo. ¡Gracias!";
const MSG_HUMANO_EN = "Of course 🌿 An administrator from the villa will contact you shortly. Thank you!";
const LETRAS = "[a-záéíóúñü]*";
const QUIEN = "(persona real|una persona|alguna persona|un ser humano|un humano|una humana|humano|(el |la |al |a la |un |una |su |tu )?(due[nñ][oa]|administrador[a]?|admin|encargad[oa]|asesor[a]?|gerente|agente|responsable|propietari[oa]|anfitri[oó]n|anfitriona))";
const RE_PIDE_ES = [
  new RegExp(`(habl|platic|comunic|comun[ií]c|comun[ií]qu|contact|cont[aá]ct|atend|ati[eé]nd|transfer|transfi[eé]r|conect|con[eé]ct|llam|ll[aá]m|pasar|p[aá]s(ame|eme|enme|anme|as|an|a)\\b)${LETRAS}[^.?!\\n]{0,30}\\b${QUIEN}(?![a-záéíóúñ])`, "i"),
  new RegExp(`(habl|platic|comunic|comun[ií]c|contact|cont[aá]ct|conect|con[eé]ct)${LETRAS}[^.?!\\n]{0,15}\\bcon alguien\\b`, "i"),
  /\b(me|nos) (llame|llamen|contacte|contacten|atienda|atiendan|escriba|escriban) (alguien|una persona|el administrador|el due[nñ]o)/i,
  /\balguien (que )?(me|nos) (pueda |puede )?(atienda|atender|llame|llamar|contacte|contactar|escriba|escribir)\b/i,
  /\b(quiero|necesito|prefiero)( a| hablar con)? (una persona|un humano|alguien real|una persona real)\b/i,
  /\bno eres (una )?persona\b|\beres (un )?(bot|robot)\b/i,
];
const RE_PIDE_EN = /\b(talk|speak|chat|connect|transfer|call)\b[^.?!\n]{0,25}\b(human|real person|a person|someone|somebody|agent|manager|owner|host|admin|representative|staff)\b|\b(live agent|human agent|real person)\b|\bare you a (bot|robot)\b/i;
const pideHablarConPersona = t => { const s = String(t || ""); return !s.startsWith("[SISTEMA]") && (RE_PIDE_ES.some(r => r.test(s)) || RE_PIDE_EN.test(s)); };

function procesarConClaude(phoneNumber, telefono, message, res) {
  db.get("SELECT messages FROM conversations WHERE id = ?", [phoneNumber], async (err, row) => {
    let history = row ? JSON.parse(row.messages) : [];
    history.push({ role: "user", content: String(message) });

    try {
      if (String(message).startsWith("[SISTEMA] PAGO_CONFIRMADO")) {
        try {
          const n = await confirmarReservas(phoneNumber);
          if (n === 0) console.log("No habia reservas pendientes para", phoneNumber);
        } catch (e) {
          console.error("Error confirmando reserva en Calendar:", e.message);
        }
      }
      // Pidio hablar con una persona: mensaje fijo, pausa inmediata y aviso a los administradores (sin llamar a Claude)
      if (pideHablarConPersona(message)) {
        const s = String(message), enIngles = RE_PIDE_EN.test(s) && !RE_PIDE_ES.some(r => r.test(s));
        const texto = enIngles ? MSG_HUMANO_EN : MSG_HUMANO_ES;
        const horas = Number(process.env.HORAS_PAUSA || 12);
        db.run("INSERT OR REPLACE INTO pausas (id, hasta) VALUES (?, ?)", [phoneNumber, Date.now() + horas * 3600000]);
        console.log("PIDE HABLAR CON PERSONA:", phoneNumber, "- agente en pausa", horas, "h");
        history.push({ role: "assistant", content: texto });
        if (history.length > 40) history.splice(0, history.length - 40);
        while (history.length && history[0].role !== "user") history.shift();
        db.run("INSERT OR REPLACE INTO conversations (id, messages, updated_at) VALUES (?, ?, datetime('now'))", [phoneNumber, JSON.stringify(history)]);
        res.json({ response: texto, avisoPago: "no", enviarFotos: "no", fotosPinatas: "no", avisoHumano: "si" });
        bitacora("Pide hablar con persona", { telefono: (telefono && !String(telefono).includes("{{")) ? telefono : phoneNumber }).catch(() => {});
        avisarAdmins({ id: phoneNumber, telefono, texto: message }).catch(e => console.error("Aviso admin:", e.message));
        return;
      }
      let enviado = false;
      const timer = setTimeout(() => {
        enviado = true;
        console.log("Respuesta lenta, se enviara completa por API a", phoneNumber);
        // Sin mensaje intermedio: ManyChat recibe vacio (la condicion res_respuesta no esta vacio lo ignora) y la respuesta completa llega por API
        res.json({ response: "", omitir: "si", avisoPago: "no", enviarFotos: "no", fotosPinatas: "no", avisoHumano: "no" });
      }, Math.max(300, LIMITE_MS - (Date.now() - (res.t0 || Date.now()))));
      let reply;
      pensando.add(phoneNumber);
      try { reply = await responderConClaude(history, phoneNumber); }
      catch (e) { pensando.delete(phoneNumber); clearTimeout(timer); if (enviado) { console.error(e); return enviarPorManyChat(phoneNumber, "Perdón, tuve un pequeño problema técnico 🙏 ¿Me repites tu último mensaje?"); } throw e; }
      pensando.delete(phoneNumber);
      // Llego otro mensaje mientras pensaba: no se manda esta respuesta, se junta con lo nuevo y se contesta una sola vez
      if (cancelados.has(phoneNumber) && pendientes.has(phoneNumber) && !/RESERVA_JSON|AVISO_PAGO|PASAR_A_HUMANO/.test(String(reply))) {
        cancelados.delete(phoneNumber);
        clearTimeout(timer);
        pendientes.get(phoneNumber).textos.unshift(String(message));
        console.log("Respuesta descartada (llego otro mensaje), se contesta todo junto a", phoneNumber);
        if (!enviado) res.json({ response: "", omitir: "si", avisoPago: "no", enviarFotos: "no", fotosPinatas: "no", avisoHumano: "no" });
        return;
      }
      cancelados.delete(phoneNumber);
      let mensajeCliente = reply;
      const match = reply.match(/RESERVA_JSON:(\{.*\})/);
      if (match) {
        mensajeCliente = reply.replace(match[0], "").trim();
        try {
          const datos = JSON.parse(match[1]);
          datos.contacto = phoneNumber;
          datos.telefono = (telefono && !String(telefono).includes("{{")) ? telefono : phoneNumber;
          const r = await crearEventoCalendar(datos);
          if (r.excedido) {
            mensajeCliente += "\n\nUna aclaración 🙏 para grupos de más de 20 personas, el administrador de la villa te dará una atención personalizada 🌿 ¿Me cuentas cuál es el plan o qué tienen en mente?";
            planGrupo.set(phoneNumber, Date.now());
          } else if (r.ocupado) {
            mensajeCliente += "\n\nAy, justo acabo de revisar y esas fechas se acaban de ocupar 😔 ¿Buscamos otras fechas cercanas?";
          } else {
            console.log("Evento creado en Calendar:", r.id);
            await bitacora("Pendiente de pago", { ...datos, eventoId: r.id });
          }
        } catch (e) {
          console.error("Error creando evento de Calendar:", e.message);
        }
      }
      const cot = mensajeCliente.match(/COTIZACION_JSON:(\{.*?\})/);
      if (cot) {
        mensajeCliente = mensajeCliente.replace(cot[0], "").trim();
        try { const q = JSON.parse(cot[1]); const f = v => String(v || "").trim().replace(/-/g, "/"), esFecha = v => /^\d{1,2}\/\d{1,2}\/\d{4}$/.test(v); q.llegada = f(q.llegada); q.salida = f(q.salida); if (!esFecha(q.llegada) || !esFecha(q.salida)) throw new Error("sin fechas, no se guarda"); db.run("INSERT OR REPLACE INTO cotizaciones (id, llegada, salida, total, creado, recordatorio) VALUES (?, ?, ?, ?, ?, NULL)", [phoneNumber, q.llegada, q.salida, q.total || 0, Date.now()]); db.run("DELETE FROM no_recordar WHERE id = ?", [phoneNumber]); console.log("Cotizacion guardada", phoneNumber, q.llegada, "-", q.salida); }
        catch (e) { console.error("Cotizacion:", e.message); }
      }
      if (mensajeCliente.includes("NO_INTERESADO")) {
        mensajeCliente = mensajeCliente.replace(/NO_INTERESADO/g, "").trim();
        db.run("INSERT OR REPLACE INTO no_recordar (id) VALUES (?)", [phoneNumber]);
        console.log("NO INTERESADO: ya no se le mandan recordatorios a", phoneNumber);
      }
      let avisoPago = "no";
      if (mensajeCliente.includes("AVISO_PAGO")) {
        avisoPago = "si";
        mensajeCliente = mensajeCliente.replace(/AVISO_PAGO/g, "").trim();
        console.log("AVISO DE PAGO de", phoneNumber);
        marcarAvisoPago(phoneNumber).catch(e => console.error("Marcar aviso de pago:", e.message));
        await bitacora("Aviso de pago", { telefono: (telefono && !String(telefono).includes("{{")) ? telefono : phoneNumber });
      }
      let enviarFotos = "no";
      if (mensajeCliente.includes("ENVIAR_FOTOS")) {
        enviarFotos = "si";
        mensajeCliente = mensajeCliente.replace(/ENVIAR_FOTOS/g, "").trim();
        console.log("FOTOS solicitadas por", phoneNumber);
      }
      // Calendario de dias libres: la IA pone CALENDARIO:AAAA-MM; si se le olvida, se detecta en el mensaje del cliente
      const calMeses = [...mensajeCliente.matchAll(/CALENDARIO:\s*(\d{4}-\d{2})/g)].map(m => m[1]);
      mensajeCliente = mensajeCliente.replace(/CALENDARIO:\s*\S*/g, "").trim();
      if (!calMeses.length && pideCalendario(message)) calMeses.push(...mesesPedidos(message));
      if (calMeses.length) {
        console.log("CALENDARIO solicitado por", phoneNumber, calMeses.join(", "));
        setTimeout(() => enviarCalendarios(phoneNumber, [...new Set(calMeses)].slice(0, 2)).catch(e => console.error("Calendario:", e.message)), 3500);
      }
      const pidePersona = false; // si pidio hablar con una persona, ya se pauso antes de llamar a Claude
      // Grupo mayor a la capacidad: se detecta en el codigo para no depender de la IA
      const txt = String(message).toLowerCase();
      const maxNum = re => Math.max(0, ...[...txt.matchAll(re)].map(m => +m[1]));
      const nAdultos = maxNum(/(\d{1,3})\s*adultos?/g);
      const nPersonas = maxNum(/(\d{1,3})\s*(personas?|pax|invitados?|huespedes?|huéspedes?|gente|asistentes?|amigos?|familiares)/g);
      const nNinos = maxNum(/(\d{1,3})\s*(niñ[oa]s?|nin[oa]s?|menores?)/g);
      const totalPersonas = Math.max(nPersonas, nAdultos + nNinos); // adultos + ninos
      const esGrupo = totalPersonas > 20; // 16-20 se cotiza con $750 por persona adicional; 21+ al administrador
      const FINAL_GRUPO = "¡Muchas gracias por compartirnos su plan! 🌿 En breve el administrador de la villa se pondrá en contacto contigo para darte una atención personalizada. ¡Gracias!";
      const espera = planGrupo.get(phoneNumber);
      if (espera && Date.now() - espera < 48 * 3600000) {
        planGrupo.delete(phoneNumber);
        console.log("PLAN DE GRUPO recibido de", phoneNumber);
        mensajeCliente = FINAL_GRUPO + "\nPASAR_A_HUMANO";
      } else if (!pidePersona && (esGrupo || (grupoGrande.get(phoneNumber) && Date.now() - grupoGrande.get(phoneNumber) < 48 * 3600000))) {
        // Grupo grande: la IA contesta con todo el contexto; el codigo solo revisa fechas y disponibilidad
        mensajeCliente = mensajeCliente.replace(/PASAR_A_HUMANO/g, "").trim();
        let f = extraerFechas(message);
        const enEsteMensaje = !!f;
        if (!f && esGrupo) {
          // Las fechas pudieron venir en un mensaje anterior (ej. "24 de diciembre" y despues "somos 20")
          const previos = history.filter(h => h.role === "user" && typeof h.content === "string").slice(-8, -1).reverse();
          for (const h of previos) { f = extraerFechas(h.content); if (f) break; }
        }
        if (esGrupo) grupoGrande.set(phoneNumber, Date.now());
        if (!f) {
          planGrupo.set(phoneNumber, Date.now()); // sin fechas: se avisa de inmediato al administrador
          console.log("GRUPO GRANDE: sin fechas, se pasa al administrador", phoneNumber);
        } else {
          let disp = { disponible: true };
          try { disp = await consultarDisponibilidad(f.llegada, f.salida); } catch (e) { console.error("Disponibilidad grupo:", e.message); }
          console.log("GRUPO GRANDE:", f.llegada, "-", f.salida, disp.disponible ? "LIBRE" : "OCUPADO", enEsteMensaje ? "(mensaje actual)" : "(mensaje anterior)", phoneNumber);
          if (!disp.disponible) {
            if (!/ocupad|no (hay|tenemos|contamos con|est[aá]n?) disponib|no est[aá]n? disponible|sin disponibilidad/i.test(mensajeCliente)) mensajeCliente = `Revisé el calendario y del ${f.llegada} al ${f.salida} ya no tenemos disponibilidad 😔 ¿Te gustaría que revisemos otras fechas para tu grupo?`;
          } else {
            grupoGrande.delete(phoneNumber);
            planGrupo.set(phoneNumber, Date.now());
            mensajeCliente = `¡Buenas noticias! 🎉 Sí tenemos disponibilidad del ${f.llegada} al ${f.salida}.\n\nPara grupos de más de 20 personas, el administrador de la villa te dará una atención personalizada. Para pasarle toda la información, ¿me cuentas cuál es el plan o qué tienen en mente? (tipo de evento o celebración y cuántas personas serían en total) 😊`;
          }
        }
        reply = mensajeCliente;
      } else if (mensajeCliente.includes("PASAR_A_HUMANO") && !pidePersona && /ocupad|no (hay|tenemos|est[aá]n?) disponib/i.test(mensajeCliente)) {
        mensajeCliente = mensajeCliente.replace(/PASAR_A_HUMANO/g, "").trim();
        console.log("GRUPO GRANDE: fechas ocupadas, no se pasa al administrador", phoneNumber);
      } else if (mensajeCliente.includes("PASAR_A_HUMANO") && !pidePersona && (totalPersonas > 20 || /capacidad|grupo|20 personas|personas en total|m[aá]s grande/i.test(mensajeCliente + " " + txt))) {
        mensajeCliente = mensajeCliente.replace(/PASAR_A_HUMANO/g, "").trim();
        if (!/plan|tienen en mente|evento|celebraci/i.test(mensajeCliente)) mensajeCliente += "\n\nPara pasarle toda la información al administrador, ¿me cuentas cuál es el plan o qué tienen en mente? (tipo de evento o celebración, fechas y cuántas personas serían en total) 😊";
        planGrupo.set(phoneNumber, Date.now());
        console.log("GRUPO GRANDE (IA): pregunto el plan a", phoneNumber);
      } else if ((totalPersonas > 20) && !mensajeCliente.includes("PASAR_A_HUMANO") && /ocupad|no (hay|tenemos|est[aá]n?) disponib|otras fechas|qu[eé] fechas|cu[aá]les fechas/i.test(mensajeCliente)) {
        // La IA ya contesto sobre disponibilidad/fechas (ocupadas o faltan fechas): se respeta su respuesta
        console.log("GRUPO GRANDE: esperando fechas libres de", phoneNumber);
      } else if ((totalPersonas > 20) && !mensajeCliente.includes("PASAR_A_HUMANO")) {
        console.log("GRUPO GRANDE:", totalPersonas, "personas (", nAdultos, "adultos /", nNinos, "ninos ) de", phoneNumber);
        mensajeCliente = "¡Qué gusto que quieran venir en grupo! 🌿 Para grupos de más de 20 personas, el administrador de la villa te dará una atención personalizada. Para pasarle toda la información, ¿me cuentas cuál es el plan o qué tienen en mente? (tipo de evento o celebración, fechas y cuántas personas serían en total) 😊";
        planGrupo.set(phoneNumber, Date.now());
      }
      // Fiesta o grupo grande: aviso INMEDIATO al administrador y pausa (ya no se espera a que el cliente cuente el plan)
      let motivoAviso = message;
      const grupoAhora = planGrupo.get(phoneNumber);
      if (grupoAhora && grupoAhora !== espera) {
        planGrupo.delete(phoneNumber); grupoGrande.delete(phoneNumber);
        mensajeCliente = "¡Qué gusto que nos consideren para su celebración! 🎉 Para fiestas y grupos grandes, el administrador de la villa te dará una atención personalizada. Ya le avisé y en breve te escribe por aquí 😊\nPASAR_A_HUMANO";
        reply = mensajeCliente;
      }
      if (/PASAR_A_HUMANO/.test(mensajeCliente) && (totalPersonas > 20 || espera || grupoAhora)) {
        motivoAviso = `🎉 FIESTA / GRUPO GRANDE${totalPersonas ? ` (${totalPersonas} personas)` : ""}: ${message}`;
      }
      let avisoHumano = "no";
      if (mensajeCliente.includes("PASAR_A_HUMANO")) {
        avisoHumano = "si";
        mensajeCliente = mensajeCliente.replace(/PASAR_A_HUMANO/g, "").trim();
        const horas = Number(process.env.HORAS_PAUSA || 12);
        db.run("INSERT OR REPLACE INTO pausas (id, hasta) VALUES (?, ?)", [phoneNumber, Date.now() + horas * 3600000]);
        console.log("PASAR A HUMANO:", phoneNumber, "- agente en pausa", horas, "h");
        await bitacora("Pide hablar con persona", { telefono: (telefono && !String(telefono).includes("{{")) ? telefono : phoneNumber }).catch(() => {});
        avisarAdmins({ id: phoneNumber, telefono, texto: motivoAviso }).then(out => console.log("Resultado aviso:", out.join(" | "))).catch(e => console.error("Aviso admin:", e.message));
      }
      let fotosPinatas = "no";
      if (mensajeCliente.includes("FOTOS_PINATAS")) {
        fotosPinatas = "si";
        mensajeCliente = mensajeCliente.replace(/FOTOS_PINATAS/g, "").trim();
        console.log("FOTOS PINATAS solicitadas por", phoneNumber);
        enviarFotos = "no";
      }
      mensajeCliente = mensajeCliente.replace(/\*\*(.+?)\*\*/g, "*$1*").replace(/^#+\s*/gm, "");
      if (!mensajeCliente.trim()) mensajeCliente = "Perfecto, ya quedo anotado 😊 ¿Algo mas en lo que te pueda ayudar?";

      history.push({ role: "assistant", content: reply });
      if (history.length > 40) history.splice(0, history.length - 40);
      while (history.length && history[0].role !== "user") history.shift();
      db.run("INSERT OR REPLACE INTO conversations (id, messages, updated_at) VALUES (?, ?, datetime('now'))",
        [phoneNumber, JSON.stringify(history)]);

      clearTimeout(timer);
      if (enviado) enviarPorManyChat(phoneNumber, mensajeCliente);
      else res.json({ response: mensajeCliente, avisoPago, enviarFotos, fotosPinatas, avisoHumano });
    } catch (error) {
      console.error(error);
      if (!res.headersSent) res.status(200).json({ response: "Perdón, tuve un pequeño problema técnico 🙏 ¿Me repites tu último mensaje?" });
    }
  });
}

