// ===================== AGENTE REVISOR DE CONVERSACIONES =====================
// Abrir en el navegador: URL/revisar?dias=7&clave=TU_CLAVE  (agrega ?nuevo=1 para rehacer el analisis)
const textoDe = c => typeof c === "string" ? c : Array.isArray(c) ? c.filter(b => b.type === "text").map(b => b.text).join(" ") : "";
const esc = s => String(s ?? "").replace(/[&<>"]/g, ch => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[ch]));
const ETAPAS = ["Solo saludó", "Preguntó fechas o precio", "Recibió cotización", "Recibió datos de pago", "Apartó (pendiente de pago)", "Avisó que pagó", "Confirmada"];
let reporteCache = null;
async function datosRevision(dias) {
  const filas = await new Promise(ok => db.all("SELECT id, messages, created_at, updated_at FROM conversations WHERE updated_at >= datetime('now', ?) ORDER BY updated_at DESC", [`-${dias} days`], (e, r) => ok(e ? [] : r || [])));
  const cot = await new Promise(ok => db.all("SELECT id FROM cotizaciones", [], (e, r) => ok(new Set((r || []).map(x => String(x.id))))));
  const pausas = await new Promise(ok => db.all("SELECT id, hasta FROM pausas", [], (e, r) => ok(new Map((r || []).map(x => [String(x.id), x.hasta])))));
  const reservas = new Map();
  try {
    const r = await calendar.events.list({ calendarId: CALENDAR_ID, timeMin: new Date(Date.now() - 60 * 86400000).toISOString(), singleEvents: true, maxResults: 250 });
    for (const e of r.data.items || []) { const p = e.extendedProperties?.private || {}; if (p.contacto && e.status !== "cancelled") reservas.set(String(p.contacto), p); }
  } catch (e) { console.error("Revisar (calendario):", e.message); }
  return filas.map(f => {
    let h = []; try { h = JSON.parse(f.messages || "[]"); } catch {}
    const msgs = h.map(x => ({ r: x.role, t: textoDe(x.content).replace(/\s+/g, " ").trim() })).filter(x => x.t && !/^\[SISTEMA\]/.test(x.t));
    const cli = msgs.filter(x => x.r === "user").map(x => x.t).join(" "), vero = msgs.filter(x => x.r === "assistant").map(x => x.t).join(" ");
    const res = reservas.get(String(f.id)) || {};
    let etapa = 0;
    if (/fecha|precio|costo|cu[aá]nto|cotiza|disponib|\d{1,2}\s*(de\s+)?(ene|feb|mar|abr|may|jun|jul|ago|sep|oct|nov|dic)|\d{1,2}[\/\-]\d{1,2}/i.test(cli)) etapa = 1;
    if (cot.has(String(f.id)) || /\$\s?\d{1,2},\d{3}/.test(vero)) etapa = 2;
    if (/CLABE|SPEI|OXXO|cuenta/i.test(vero) && etapa >= 2) etapa = 3;
    if (res.estado === "pendiente") etapa = 4;
    if (res.pago || /comprobante|ya (deposit|pagu|transfer)/i.test(cli)) etapa = Math.max(etapa, 5);
    if (res.estado === "confirmada") etapa = 6;
    const ult = msgs[msgs.length - 1] || { r: "-" };
    const horas = (Date.now() - new Date(String(f.updated_at).replace(" ", "T") + "Z").getTime()) / 3600000;
    return { id: String(f.id), etapa, msgs, horas, sinRespuesta: ult.r === "user", pausada: (pausas.get(String(f.id)) || 0) > Date.now() };
  });
}
async function analizarConClaude(convs) {
  const abiertas = convs.filter(c => c.etapa < 6).slice(0, 40);
  if (!abiertas.length) return { resumen: "No hay conversaciones abiertas en el periodo.", causas: [], cambios_vero: [], conversaciones: [] };
  const texto = abiertas.map(c => `### ID ${c.id} | etapa: ${ETAPAS[c.etapa]} | ultimo mensaje de: ${c.sinRespuesta ? "CLIENTE (Vero no contesto)" : "Vero"} | hace ${Math.round(c.horas)} h\n` + c.msgs.slice(-14).map(m => `${m.r === "user" ? "C" : "V"}: ${m.t.slice(0, 280)}`).join("\n")).join("\n\n");
  const r = await client.messages.create({
    model: "claude-sonnet-5", max_tokens: 8000, thinking: { type: "disabled" },
    system: "Eres el analista comercial de Villa de Canto (casa de descanso en Amazcala, Queretaro, para hasta 20 personas; tarifas $10,500 dom-jue, $12,000 viernes, $14,000 sabado; anticipo $5,000 + deposito $5,000). Vero es la asistente de IA que atiende WhatsApp. Revisa conversaciones que NO terminaron en reserva y explica con honestidad por que se cayeron (precio, fechas ocupadas, Vero contesto mal o lento, Vero no contesto, falta de seguimiento, cliente solo cotizaba, etc.). Responde SOLO un JSON valido, sin texto extra, con esta forma: {\"resumen\":\"2-3 frases\",\"causas\":[{\"causa\":\"\",\"cuantas\":0,\"solucion\":\"\"}],\"cambios_vero\":[\"cambio concreto a las instrucciones de Vero\"],\"conversaciones\":[{\"id\":\"\",\"motivo\":\"1 frase\",\"accion\":\"que debe hacer el administrador\",\"mensaje\":\"mensaje corto y calido para reenganchar por WhatsApp, o vacio si no conviene\"}]}. Maximo 6 causas y 6 cambios, ordenados por impacto.",
    messages: [{ role: "user", content: `Hoy es ${hoyMexico()}. Conversaciones abiertas:\n\n${texto}` }],
  });
  const raw = r.content.filter(b => b.type === "text").map(b => b.text).join("");
  try { return JSON.parse(raw.slice(raw.indexOf("{"), raw.lastIndexOf("}") + 1)); }
  catch { return { resumen: raw.slice(0, 600), causas: [], cambios_vero: [], conversaciones: [] }; }
}
function htmlReporte(dias, convs, a, nombres) {
  const porId = new Map((a.conversaciones || []).map(c => [String(c.id), c]));
  const conteo = ETAPAS.map((n, i) => ({ n, c: convs.filter(x => x.etapa === i).length }));
  const sinResp = convs.filter(c => c.sinRespuesta).length;
  const td = "padding:12px 14px;border-bottom:2px solid #1b2b34;vertical-align:top;";
  const filas = convs.filter(c => c.etapa < 6).map(c => { const x = porId.get(c.id) || {}; const ventana = c.horas < 23;
    return `<tr><td style="${td}"><b>${esc(nombres.get(c.id) || "Contacto")}</b><br><span style="color:#4b5a62;font-size:13px">${esc(c.id)}</span></td><td style="${td}">${esc(ETAPAS[c.etapa])}${c.pausada ? '<br><span style="color:#2e6f90;font-size:13px">Vero en pausa</span>' : ""}</td><td style="${td}">${c.sinRespuesta ? '<b style="color:#b3261e">Cliente sin respuesta</b>' : "Vero"}<br><span style="color:#4b5a62;font-size:13px">hace ${c.horas < 48 ? Math.round(c.horas) + " h" : Math.round(c.horas / 24) + " d"}</span></td><td style="${td}">${esc(x.motivo || "")}</td><td style="${td}">${esc(x.accion || "")}</td><td style="${td}">${x.mensaje ? `<div style="background:#f5efe9;padding:10px">${esc(x.mensaje)}</div>` : ""}${ventana ? `<div style="margin-top:8px"><a href="/continuar/${encodeURIComponent(c.id)}" target="_blank">Que Vero retome →</a></div>` : '<div style="margin-top:8px;color:#4b5a62;font-size:13px">Fuera de 24 h: escríbele con plantilla</div>'}</td></tr>`; }).join("");
  return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Revisión de conversaciones · Villa de Canto</title><style>body{margin:0;background:#e2d6cb;color:#1b2b34;font-family:Archivo,Helvetica,Arial,sans-serif}a{color:#24597a}a:hover{color:#1b2b34}</style></head><body><div style="max-width:1280px;margin:0 auto;padding:40px 24px;display:flex;flex-direction:column;gap:32px">
<div style="border-bottom:2px solid #1b2b34;padding-bottom:20px"><div style="font-weight:700;letter-spacing:.12em;color:#2e6f90">VILLA DE CANTO · ÚLTIMOS ${dias} DÍAS</div><h1 style="font-size:48px;margin:8px 0 0;line-height:1">Revisión de conversaciones</h1></div>
<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));border-top:2px solid #1b2b34;border-left:2px solid #1b2b34">${[{ n: "Conversaciones", c: convs.length }, { n: "Sin respuesta de Vero", c: sinResp }, ...conteo].map(k => `<div style="padding:16px;border-right:2px solid #1b2b34;border-bottom:2px solid #1b2b34"><div style="font-size:36px;font-weight:700">${k.c}</div><div style="font-size:14px;color:#4b5a62">${esc(k.n)}</div></div>`).join("")}</div>
<div style="font-size:20px;line-height:1.5">${esc(a.resumen || "")}</div>
<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:32px"><div><h2 style="border-bottom:2px solid #1b2b34;padding-bottom:8px">Por qué no se cierran</h2>${(a.causas || []).map(c => `<div style="padding:12px 0;border-bottom:2px solid #1b2b34"><b>${esc(c.causa)}</b> · ${esc(c.cuantas)}<br><span style="color:#4b5a62">${esc(c.solucion)}</span></div>`).join("")}</div><div><h2 style="border-bottom:2px solid #1b2b34;padding-bottom:8px">Cambios sugeridos a Vero</h2>${(a.cambios_vero || []).map(c => `<div style="padding:12px 0;border-bottom:2px solid #1b2b34">${esc(c)}</div>`).join("")}</div></div>
<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:15px;border-top:2px solid #1b2b34"><tr style="text-align:left;background:#1b2b34;color:#e2d6cb"><th style="padding:12px 14px">Contacto</th><th style="padding:12px 14px">Etapa</th><th style="padding:12px 14px">Último</th><th style="padding:12px 14px">Por qué se frenó</th><th style="padding:12px 14px">Qué hacer</th><th style="padding:12px 14px">Mensaje sugerido</th></tr>${filas}</table></div>
<div style="color:#4b5a62;font-size:13px">Generado ${esc(new Date().toLocaleString("es-MX", { timeZone: "America/Mexico_City" }))}. Se guarda 30 min; agrega &amp;nuevo=1 para rehacerlo.</div></div></body></html>`;
}
app.get("/revisar", async (req, res) => {
  if (process.env.CLAVE_REVISION && req.query.clave !== process.env.CLAVE_REVISION) return res.status(401).send("Falta la clave: /revisar?clave=...");
  const dias = Math.min(60, Math.max(1, Number(req.query.dias) || 7));
  if (reporteCache && reporteCache.dias === dias && !req.query.nuevo && Date.now() - reporteCache.t < 30 * 60000) return res.send(reporteCache.html);
  try {
    const convs = await datosRevision(dias);
    const [a, nombres] = await Promise.all([
      analizarConClaude(convs),
      Promise.all(convs.slice(0, 60).map(async c => { const i = await infoContacto(c.id).catch(() => ({})); return [c.id, i.name || [i.first_name, i.last_name].filter(Boolean).join(" ")]; })).then(x => new Map(x)),
    ]);
    const html = htmlReporte(dias, convs, a, nombres);
    reporteCache = { t: Date.now(), dias, html };
    console.log("Revision generada:", convs.length, "conversaciones");
    res.send(html);
  } catch (e) { console.error("Revisar:", e.message); res.status(500).send("Error al revisar: " + esc(e.message)); }
});

